FORMAT = 'rdf4j-phase-admission-comparison-v1'
ARMS = ('ordinary', 'initial', 'always')
PAIRS = (('always', 'initial'), ('initial', 'ordinary'), ('always', 'ordinary'))
# Chosen prospectively, before timing: each of three fixtures occupies each position twice.
# Among all 720 assignments of the six fixture permutations to the six fixed arm orders,
# this assignment minimizes repeated (fixture position, arm position) cells (five repeats).
THREE_FIXTURE_ORDERS = ((0, 1, 2), (0, 2, 1), (1, 0, 2), (1, 2, 0), (2, 1, 0), (2, 0, 1))
SOURCE_SUFFIXES = {'.java', '.py', '.xml', '.properties'}
RAW_FILES = ('launch.json', 'process.json', 'inputs-before.json', 'inputs-after.json',
             'console.log', 'samples.jsonl', 'gc.log', 'validation.json')
METRICS = ('totalNs', 'allThreadAllocatedBytes', 'callerThreadAllocatedBytes', 'connectionNs',
           'prepareNs', 'evaluateNs', 'firstRowAfterEvaluateNs', 'prefixConsumeNs', 'tailConsumeNs',
           'consumeNs', 'closeNs', 'retainedReadNs', 'ledgerPeakBytes')
NULLABLE_METRICS = {'firstRowAfterEvaluateNs', 'prefixConsumeNs', 'tailConsumeNs'}
OWNER_FIELDS = ('ownerOrdinal', 'compileOrdinalAtOpen', 'compileOrdinalAtClose',
                'lazyValueCallsAtOpen', 'lazyValueCallsAtClose', 'probes', 'hits', 'collisions',
                'invalidations', 'unsupportedValues', 'clearCalls', 'resizes', 'rehashDiscards',
                'lowHitDisable', 'initialAdmissionRefusals', 'growthAdmissionRefusals', 'peakCapacity',
                'peakArrayBytes', 'retainedEntriesAtClose', 'capacityAtClose', 'arrayBytesAfterClose',
                'disabledAtClose', 'collectedMisses', 'weakEntryAllocations', 'ownerReferenceAllocations',
                'peakReservationBytes', 'weakRetention')
ZERO_OWNER_FIELDS = ('invalidations', 'unsupportedValues', 'rehashDiscards',
                     'initialAdmissionRefusals', 'growthAdmissionRefusals', 'arrayBytesAfterClose')
OWNER_EVENTS = ('probes', 'hits', 'collisions', 'invalidations', 'unsupportedValues', 'clearCalls',
                'resizes', 'rehashDiscards', 'lowHitDisable', 'initialAdmissionRefusals',
                'growthAdmissionRefusals', 'collectedMisses', 'weakEntryAllocations', 'ownerReferenceAllocations')
ROUTE_COUNTERS = ('irPlanned', 'irOpened', 'irRows', 'semanticNativeCompiles', 'compiledBinds',
                  'interpretedBinds', 'aggregateCompiledBinds', 'aggregateInterpretedBinds',
                  'hostedGeneric', 'unhostedHardDeclines', 'chunkEngaged',
                  'leftJoinReplayMaterializations', 'factorizedEngagement')
ORDERED_COUNTERS = {'semanticNativeCompiles': 1, 'irPlanned': 0, 'irOpened': 0, 'irRows': 0,
                    'compiledBinds': 0, 'interpretedBinds': 0, 'aggregateCompiledBinds': 0,
                    'aggregateInterpretedBinds': 0, 'chunkEngaged': 1, 'factorizedEngagement': 1}
ORDERED_SELECTIONS = [{'point': 'ORDER', 'label': 'ORDER BY dispatch',
                       'strategy': 'orderedFactorizedSort', 'mode': 'normal', 'count': 1}]
ARGUMENT_KEYS = ('pattern', 'prefix-probes', 'tail-probes', 'working-set', 'bootstrap-keys', 'width',
                 'large-keys', 'large-payload-chars', 'consumption', 'limit', 'retain')
DIMENSION_METADATA = {'prefix-probes': 'prefixProbes', 'tail-probes': 'tailProbes',
                      'working-set': 'workingSet', 'bootstrap-keys': 'bootstrapKeys', 'width': 'width',
                      'large-keys': 'largeKeys', 'large-payload-chars': 'largePayloadChars',
                      'pattern': 'pattern', 'consumption': 'consumption', 'limit': 'earlyLimit',
                      'retain': 'retainLimit'}


def require(condition, message):
    if not condition:
        raise ValueError(message)


def sha(path):
    with Path(path).open('rb') as stream:
        return hashlib.file_digest(stream, 'sha256').hexdigest()


def object_sha(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, allow_nan=False).encode()).hexdigest()


def read(path):
    return json.loads(Path(path).read_text())


def json_lines(path):
    return [json.loads(line) for line in Path(path).read_text().splitlines() if line.strip()]


def claim_name(ordinal):
    return f'{ordinal:04d}.json'


def fixture_order(fixtures, round_index):
    names = list(fixtures)
    if len(names) == 3:
        return [names[i] for i in THREE_FIXTURE_ORDERS[round_index]]
    return names if round_index % 2 == 0 else list(reversed(names))


def nonnegative_int(value):
    return type(value) is int and value >= 0


def subset(actual, expected, label):
    require(isinstance(actual, dict) and isinstance(expected, dict), label + ': object required')
    for key, value in expected.items():
        require(key in actual, label + ': missing ' + key)
        if isinstance(value, dict):
            subset(actual[key], value, label + '.' + key)
        else:
            require(type(actual[key]) is type(value) and actual[key] == value,
                    label + ': mismatch for ' + key)


def validate_definitions(definitions):
    """Return ordered fixtures from a root-approved, independently qualified JSON file.

    Schema: {"format":1,"fixtures":[{"id":...,"arguments":{all ARGUMENT_KEYS},
      "oracle":{"rows":consumed,"fullRows":full,"checksum":string,"fullChecksum":string},
      "metadata":{"querySha256":...,"insertionRecipeSha256":..., ...},
      "qualification":{"measuredTier":"compiled"|"interpreted"|"ordered-factorized",
        "minimumAdjacencyLookupHits":integer,"adjacencyExplanation":string,
        "sampleCounters":{"semanticNativeCompiles":1,"irOpened":1,"irRows":...},
        "projection":{"nativeProjectedRows":...,"projectedBindingSetsCreated":...}}}]}

    All dimensions are explicit; no harness-default changes can alter a frozen command.
    Admission outcomes are observations, not admission-to-the-dataset gates.
    """
    require(definitions.get('format') == 1 and isinstance(definitions.get('fixtures'), list)
            and definitions['fixtures'], 'Expected a nonempty ordered fixture definition list')
    result = {}
    for fixture in definitions['fixtures']:
        require(set(fixture) == {'id', 'arguments', 'oracle', 'metadata', 'qualification'},
                'Wrong fixture definition fields')
        name = fixture['id']
        require(isinstance(name, str) and re.fullmatch('[a-z0-9][a-z0-9-]{0,59}', name)
                and name not in result, 'Invalid or duplicate fixture ID')
        args = fixture['arguments']
        require(set(args) == set(ARGUMENT_KEYS), name + ': every CLI dimension must be explicit')
        require(args['pattern'] in ('cold-hot', 'hot-unique', 'warm-cycle')
                and args['consumption'] in ('full', 'early', 'retained'), name + ': invalid pattern/consumer')
        require(all(nonnegative_int(args[k]) for k in ARGUMENT_KEYS if k not in ('pattern', 'consumption')),
                name + ': dimensions must be nonnegative integers')
        p, t, width, working = (args[k] for k in ('prefix-probes', 'tail-probes', 'width', 'working-set'))
        require(1 <= width <= 32 and p > 0 and t > 0 and p + t <= 1048576
                and p % width == t % width == 0 and width <= working <= 65536
                and args['limit'] > 0, name + ': invalid phase dimensions')
        require(args['pattern'] != 'cold-hot' or p >= working, name + ': cold-hot prefix is too short')
        require(args['pattern'] != 'warm-cycle' or width <= args['bootstrap-keys'] <= p,
                name + ': warm-cycle bootstrap is too small')
        keys = p if args['pattern'] == 'cold-hot' else (working + t if args['pattern'] == 'hot-unique'
                                                       else args['bootstrap-keys'] + working)
        require(keys <= 262144 and args['large-keys'] <= keys
                and 64 <= args['large-payload-chars'] <= 2097152
                and args['large-keys'] * args['large-payload-chars'] <= 64 * 1024 * 1024,
                name + ': fixture key/payload bound exceeded')
        oracle = fixture['oracle']
        require(set(oracle) == {'rows', 'fullRows', 'checksum', 'fullChecksum'}, name + ': wrong oracle fields')
        full = (p + t) // width
        consumed = min(args['limit'], full) if args['consumption'] == 'early' else full
        require(nonnegative_int(oracle['fullRows']) and nonnegative_int(oracle['rows'])
                and oracle['fullRows'] == full and oracle['rows'] == consumed, name + ': wrong row oracle')
        require(all(isinstance(oracle[k], str) and re.fullmatch('-?[0-9]+', oracle[k])
                    for k in ('checksum', 'fullChecksum')), name + ': checksums must be decimal strings')
        require(consumed != full or oracle['checksum'] == oracle['fullChecksum'], name + ': full checksum differs')
        metadata = fixture['metadata']
        require(isinstance(metadata, dict) and all(isinstance(metadata.get(k), str)
                and re.fullmatch('[0-9a-f]{64}', metadata[k])
                for k in ('querySha256', 'insertionRecipeSha256')), name + ': missing exact dataset/query identities')
        forbidden = {'arm', 'source', 'store', 'admission', 'jvmArguments', 'systemProperties'}
        require(not forbidden.intersection(metadata), name + ': metadata cannot override arm/runtime identity')
        qualified = fixture['qualification']
        require(set(qualified) == {'measuredTier', 'minimumAdjacencyLookupHits', 'adjacencyExplanation',
                                   'sampleCounters', 'projection'}, name + ': wrong qualification fields')
        require(qualified['measuredTier'] in ('compiled', 'interpreted', 'ordered-factorized')
                and nonnegative_int(qualified['minimumAdjacencyLookupHits'])
                and isinstance(qualified['adjacencyExplanation'], str) and qualified['adjacencyExplanation'].strip(),
                name + ': incomplete route/adjacency qualification')
        counters = qualified['sampleCounters']
        require(isinstance(counters, dict) and {'semanticNativeCompiles', 'irOpened', 'irRows'} <= set(counters)
                and set(counters) <= set(ROUTE_COUNTERS)
                and all(nonnegative_int(v) for v in counters.values())
                and counters['semanticNativeCompiles'] == 1, name + ': no qualified native iteration')
        if qualified['measuredTier'] == 'ordered-factorized':
            subset(counters, ORDERED_COUNTERS, name + ': qualified ordered-factorized counters')
        else:
            require(counters['irOpened'] > 0 and counters['irRows'] > 0, name + ': no qualified native IR iteration')
        projection = qualified['projection']
        require(set(projection) == {'nativeProjectedRows', 'projectedBindingSetsCreated'}
                and all(nonnegative_int(v) for v in projection.values())
                and projection['nativeProjectedRows'] == consumed,
                name + ': incomplete projected-value opportunity qualification')
        result[name] = fixture
    return result


def verify_inputs(inputs):
    for item in inputs:
        root = Path(item['path'])
        if item['kind'] == 'tree':
            files = [p for p in root.rglob('*') if p.is_file()
                     and (not item['sourceOnly'] or p.suffix in SOURCE_SUFFIXES)]
            require({p.relative_to(root).as_posix() for p in files} == {f['name'] for f in item['files']},
                    'Frozen directory membership changed: ' + str(root))
            checks = [(root / f['name'], f) for f in item['files']]
        else:
            require(item['kind'] == 'file', 'Unknown input kind')
            checks = [(root, item)]
        for path, expected in checks:
            require(path.stat().st_size == expected['bytes'] and sha(path) == expected['sha256'],
                    'Frozen bytes changed: ' + str(path))


def frozen_protocol(cohort, check_inputs=True):
    require(sha(cohort / 'protocol.json') == (cohort / 'protocol.sha256').read_text().strip(), 'Protocol seal mismatch')
    protocol = read(cohort / 'protocol.json')
    require(protocol['format'] == FORMAT and protocol['cohort'] == str(cohort), 'Wrong protocol/cohort')
    require(protocol['analyzer'] == str(Path(__file__).resolve()), 'Wrong analyzer')
    require(protocol['arms'] == list(ARMS) and protocol['warmups'] == 8
            and protocol['measurements'] == 5 and protocol['rounds'] == 6, 'Fixed design changed')
    fixture_file = Path(protocol['fixtureDefinitionsFile'])
    require(sha(fixture_file) == protocol['fixtureDefinitionsSha256'], 'Fixture definitions changed')
    fixtures = validate_definitions(read(fixture_file))
    require(protocol['fixtures'] == fixtures and protocol['fixtureOrder'] == list(fixtures), 'Wrong fixture set/order')
    expected_order = [(i, fi, fixture, pos, arm)
                      for i, order in enumerate(itertools.permutations(ARMS))
                      for fi, fixture in enumerate(fixture_order(fixtures, i))
                      for pos, arm in enumerate(order)]
    actual_order = [(s['round'], s['fixturePosition'], s['fixture'], s['position'], s['arm'])
                    for s in protocol['schedule']]
    require(actual_order == expected_order and [s['ordinal'] for s in protocol['schedule']] ==
            list(range(len(expected_order))), 'Balanced finite schedule changed')
    require(protocol['roundFixtureOrders'] == [fixture_order(fixtures, i) for i in range(6)],
            'Prospectively chosen fixture order changed')
    count = len(expected_order)
    require(protocol['expectedCounts'] == {'jvms': count, 'queries': count * 13,
            'warmups': count * 8, 'measurements': count * 5}, 'Wrong scheduled counts')
    require(object_sha(protocol['inputs']) == protocol['inputIdentity'], 'Input identity is inconsistent')
    for slot in protocol['schedule']:
        require(Path(slot['directory']).parent == cohort, 'Run directory is outside its cohort')
        expected_properties = {'rdf4j.lmdb.resultCoordinateTransport': 'off',
            'rdf4j.lmdb.nativeValueMemo.enabled': str(slot['arm'] != 'ordinary').lower(),
            'rdf4j.lmdb.nativeValueMemo.retention': 'weak',
            'rdf4j.lmdb.nativeValueMemo.admission': 'always' if slot['arm'] == 'always' else 'initial'}
        require(slot['properties'] == expected_properties, 'Arm is not the cutoff-only ablation')
        command = slot['command']
        folder = Path(slot['directory'])
        args = fixtures[slot['fixture']]['arguments']
        expected_command = [protocol['java'], *protocol['jvmArguments'],
            '-Xlog:gc:file=' + str(folder / 'gc.log') + ':uptime,level,tags',
            *['-D' + key + '=' + value for key, value in expected_properties.items()],
            '-cp', ':'.join(protocol['classpath']), protocol['main'], '--arm=' + slot['arm'],
            '--source=' + protocol['sourceIdentity'], '--warmup=8', '--iterations=5', '--trace=false',
            '--exact-oracle=false', *['--' + key + '=' + str(value) for key, value in args.items()],
            '--output=' + str(folder / 'samples.jsonl'), '--store=' + str(folder / 'store')]
        require(command == expected_command, 'A frozen command differs from the matched design')
    if check_inputs:
        verify_inputs(protocol['inputs'])
    return protocol


def gc_summary(path):
    lines = Path(path).read_text().splitlines()
    require(any('Using G1' in line for line in lines), 'GC log does not identify G1')
    require(not any(cause in line for line in lines for cause in
                    ('System.gc()', 'Diagnostic Command', 'Heap Inspection Initiated GC')),
            'Explicit or diagnostic GC observed in a latency JVM')
    ids, pauses, concurrent, kinds = set(), [], [], Counter()
    for line in lines:
        match = re.search(r'GC\((\d+)\) (.*)$', line)
        if not match:
            continue
        ids.add(int(match.group(1)))
        body = match.group(2)
        duration = re.search(r' ([0-9]+(?:\.[0-9]+)?)ms$', body)
        if duration is None:
            continue
        elapsed = float(duration.group(1))
        if body.startswith('Pause '):
            pauses.append(elapsed)
            kinds[' '.join(body.split()[:2])] += 1
        elif body.startswith('Concurrent '):
            concurrent.append(elapsed)
    return {'scope': 'Whole JVM: fixture setup, all warmups and measured queries',
            'gcIdsObserved': len(ids), 'pauseCount': len(pauses), 'pauseMs': sum(pauses),
            'pauseMaxMs': max(pauses, default=0), 'pauseKinds': dict(kinds),
            'completedConcurrentCycles': len(concurrent), 'concurrentCycleMs': sum(concurrent),
            'interpretation': 'Concurrent durations overlap other work; never add them to pause time.'}


def route(sample):
    return {'selections': sample['successfulSelections'],
            'counters': {key: sample['counters'][key] for key in ROUTE_COUNTERS},
            'nativeProjectedRows': sample['nativeProjectedRows'],
            'adjacency': sample['adjacency']}


def normalized_metadata(metadata):
    result = {key: value for key, value in metadata.items() if key not in ('arm', 'store', 'admission')}
    differences = {'rdf4j.lmdb.nativeValueMemo.enabled', 'rdf4j.lmdb.nativeValueMemo.admission'}
    result['jvmArguments'] = [('-Xlog:gc:file=<per-JVM>:uptime,level,tags' if arg.startswith('-Xlog:gc:file=')
                              else arg) for arg in metadata['jvmArguments']
                             if not any(arg.startswith('-D' + key + '=') for key in differences)]
    result['systemProperties'] = {key: value for key, value in metadata['systemProperties'].items()
                                  if key not in differences}
    return result


def metric_values(sample):
    result = {key: sample[key] for key in METRICS}
    result.update({key: sample[key] for key in ('projectedOpportunities', 'projectedBindingSetsCreated',
                  'projectedMaterializedValues', 'sourceLazyCallsAtPrefixBoundary',
                  'projectedMaterializedValuesAtPrefixBoundary')})
    result['lazyValueCalls'] = sample['counters']['lazyValueCalls']
    boundary = sample['sourceLazyCallsAtPrefixBoundary']
    result['sourceLazyCallsAfterPrefixBoundary'] = None if boundary is None else result['lazyValueCalls'] - boundary
    return result


def aggregate(values, function=statistics.median):
    values = list(values)
    require(values and (all(v is None for v in values) or all(v is not None for v in values)),
            'A nullable metric changed availability across matched samples')
    return None if values[0] is None else function(values)


def inspect_owner(protocol, owner, sample, query_index, arm):
    require(set(owner) == set(OWNER_FIELDS) and all(nonnegative_int(owner[k]) for k in OWNER_FIELDS),
            'Malformed memo owner record')
    require(owner['ownerOrdinal'] == owner['compileOrdinalAtOpen'] == owner['compileOrdinalAtClose'] == query_index + 1,
            'Memo is not one-to-one with its native query')
    interval = owner['lazyValueCallsAtClose'] - owner['lazyValueCallsAtOpen']
    require(0 <= interval <= sample['counters']['lazyValueCalls'], 'Impossible owner resolver interval')
    probes, hits, resizes, capacity = (owner[k] for k in ('probes', 'hits', 'resizes', 'peakCapacity'))
    require(sum(owner[k] for k in ('hits', 'collisions', 'invalidations', 'collectedMisses')) <= probes,
            'Impossible memo probe partition')
    require(all(owner[k] == 0 for k in ZERO_OWNER_FIELDS), 'Unexpected identity/refusal/cleanup event')
    require(owner['weakRetention'] == 1 and owner['ownerReferenceAllocations'] <= owner['weakEntryAllocations'],
            'Wrong weak-retention or owner-reference observation')
    if probes == 0:
        require(all(owner[k] == 0 for k in (*OWNER_EVENTS, 'peakCapacity', 'peakArrayBytes',
                    'retainedEntriesAtClose', 'capacityAtClose', 'peakReservationBytes', 'disabledAtClose')),
                'An unused memo reports allocation or adaptation')
        return
    require(0 <= resizes <= 4 and capacity == 4096 << resizes
            and (resizes == 0 or probes >= 8192 * (resizes + 1)), 'Invalid growth history')
    require(resizes == 0 or (hits >= 2048 * (resizes + 1)
                            and owner['collisions'] >= 1024 * (resizes + 1)),
            'Growth cannot precede its minimum cumulative hit/collision counts')
    reservation = protocol['metadataReservation']
    def arrays(n):
        return reservation['arrayBase'] + reservation['arrayPerSlot'] * n
    def reserved(n):
        return arrays(n) + reservation['weakMetadataPerSlot'] * n + reservation['weakMetadataOverlap']
    array_peak = arrays(capacity) + (arrays(capacity // 2) if resizes else 0)
    reserved_peak = reserved(capacity) + (reserved(capacity // 2) if resizes else 0)
    require(owner['peakArrayBytes'] == array_peak and owner['peakReservationBytes'] == reserved_peak
            and reserved_peak <= sample['ledgerPeakBytes'], 'Memo reservation accounting mismatch')
    require(owner['disabledAtClose'] == owner['lowHitDisable'] in (0, 1)
            and owner['retainedEntriesAtClose'] <= owner['capacityAtClose'], 'Invalid owner terminal state')
    if owner['lowHitDisable']:
        require(arm == 'initial' and probes == 8192 and 4 * hits < 8192 and resizes == 0
                and owner['capacityAtClose'] == owner['retainedEntriesAtClose'] == 0, 'Invalid initial cutoff')
    else:
        require(owner['capacityAtClose'] == capacity, 'Live table lost its charged storage before close')
        if arm == 'initial':
            require(probes < 8192 or 4 * hits >= 8192, 'Initial mode cannot have survived its first window')


def inspect_slot(protocol, slot, require_completion):
    folder, arm = Path(slot['directory']), slot['arm']
    cohort = Path(protocol['cohort'])
    fixture = protocol['fixtures'][slot['fixture']]
    args, oracle, qualified = fixture['arguments'], fixture['oracle'], fixture['qualification']
    claim_file = cohort / 'claims' / claim_name(slot['ordinal'])
    claim, launch, process = read(claim_file), read(folder / 'launch.json'), read(folder / 'process.json')
    require(claim['ordinal'] == launch['ordinal'] == slot['ordinal']
            and claim['command'] == launch['argv'] == slot['command']
            and claim['cwd'] == launch['cwd'] == protocol['cwd']
            and claim['protocolSha256'] == sha(cohort / 'protocol.json'), 'Claim/command mismatch')
    require(process['exitCode'] == 0 and process['failure'] is None
            and process['startedEpochNs'] == launch['startedEpochNs'] >= claim['claimedEpochNs']
            and process['finishedEpochNs'] >= process['startedEpochNs'], 'JVM did not terminate normally')
    before, after = read(folder / 'inputs-before.json'), read(folder / 'inputs-after.json')
    require(before['verified'] is after['verified'] is True
            and before['inputIdentity'] == after['inputIdentity'] == protocol['inputIdentity']
            and before['checkedEpochNs'] <= claim['claimedEpochNs'] <= process['startedEpochNs']
            and after['checkedEpochNs'] >= process['finishedEpochNs'], 'Input verification interval mismatch')
    if require_completion:
        completion = read(folder / 'completion.json')
        require(completion['ordinal'] == slot['ordinal']
                and completion['protocolSha256'] == sha(cohort / 'protocol.json')
                and completion['claimSha256'] == sha(claim_file)
                and completion['completedEpochNs'] >= after['checkedEpochNs']
                and set(completion['rawHashes']) == set(RAW_FILES), 'Completion receipt mismatch')
        require(all(sha(folder / name) == value for name, value in completion['rawHashes'].items()),
                'Raw output changed after completion')
    require(not (folder / 'projected-trace.jsonl').exists(), 'Diagnostic trace leaked into a timing slot')
    records = json_lines(folder / 'samples.jsonl')
    require(len(records) == 15 and records[0].get('type') == 'metadata'
            and records[-1].get('type') == 'completion', 'Expected metadata, 13 samples, then completion')
    metadata, samples, end = records[0], records[1:-1], records[-1]
    expected = {**fixture['metadata'], **protocol['configuration'],
                **{field: args[key] for key, field in DIMENSION_METADATA.items()},
                'formatVersion': 1, 'fixture': 'ordered-phase-value-memo', 'arm': arm,
                'source': protocol['sourceIdentity'], 'store': str(folder / 'store'),
                'admission': 'always' if arm == 'always' else 'initial',
                'expectedRows': oracle['fullRows'], 'expectedChecksum': oracle['fullChecksum'],
                'expectedConsumedRows': oracle['rows'], 'expectedConsumedChecksum': oracle['checksum'],
                'projectedNames': ['v' + str(i) for i in range(args['width'])],
                'projectedOpportunities': args['prefix-probes'] + args['tail-probes'],
                'ordered': True, 'reopenedAfterPopulation': True, 'retainedOrderedRows': True,
                'sourceCacheSettingsChanged': False, 'trace': False, 'timingEligible': True,
                'exactOracle': False, 'oracleMode': 'checksum', 'timingAccepted': False,
                'memoStatisticsCapacity': 13,
                'warmup': 8, 'measurementsToRun': 5, 'maxHeapBytes': 1073741824,
                'javaVersion': protocol['javaVersion']}
    subset(metadata, expected, 'Fixture/JVM metadata')
    require(metadata['jvmArguments'] == slot['command'][1:slot['command'].index('-cp')], 'Observed JVM flags differ')
    require(metadata['systemProperties'] == {'rdf4j.lmdb.hotCounters': 'true',
            'rdf4j.lmdb.queryMemory.perQueryMaxBytes': '536870912', **slot['properties']}, 'Observed properties differ')
    setup = metadata['adjacencySetup']
    require(setup['state'] == 'ACTIVE' and setup['currentRevisionReady'] is True
            and setup['appliedRevision'] == setup['currentDataRevision'], 'Adjacency setup is not current/active')
    require([s['iteration'] for s in samples] == list(range(-8, 5))
            and [s['stage'] for s in samples] == ['warmup'] * 8 + ['measurement'] * 5, 'Wrong query chronology')
    owners = []
    for index, sample in enumerate(samples):
        expected_retained = min(args['retain'], oracle['rows']) if args['consumption'] == 'retained' else 0
        subset(sample, {'type': 'sample', 'arm': arm, 'admission': expected['admission'],
            'consumption': args['consumption'], 'rows': oracle['rows'], 'checksum': oracle['checksum'],
            'expectedChecksum': oracle['checksum'], 'expectedFullChecksum': oracle['fullChecksum'],
            'retainedRows': expected_retained, 'complete': oracle['rows'] == oracle['fullRows'],
            'projectedOpportunities': oracle['rows'] * args['width'], 'nativeProjectedRows': oracle['rows'],
            'prefixRowsConsumed': min(oracle['rows'], args['prefix-probes'] // args['width']),
            'tailRowsConsumed': max(0, oracle['rows'] - args['prefix-probes'] // args['width']),
            **{k: True for k in ('valid', 'rowCountValid', 'checksumValid',
               'ledgerReleased', 'memoLifecycleValid', 'autoRequested', 'auto', 'nativeRouteObserved', 'timingEligible')},
            'exactOracle': False, 'oracleMode': 'checksum', 'timingAccepted': False,
            'orderedExactLexicalOracleValid': None,
            'ledgerBeforeBytes': 0, 'ledgerAfterBytes': 0, 'queryLedgerPeakBytes': None,
            'omittedSelections': 0, 'memoOverflowCount': 0}, 'Result/lifetime oracle')
        for key in METRICS:
            require(nonnegative_int(sample[key]) or (key in NULLABLE_METRICS and sample[key] is None),
                    'Invalid timing/allocation metric: ' + key)
        require(sample['totalNs'] > 0 and sample['allThreadAllocatedBytes'] > 0
                and sum(sample[k] for k in ('connectionNs', 'prepareNs', 'evaluateNs', 'consumeNs',
                                           'closeNs', 'retainedReadNs')) == sample['totalNs'], 'Timing intervals do not reconcile')
        require(sample['firstRowAfterEvaluateNs'] is not None
                and sample['firstRowAfterEvaluateNs'] <= sample['consumeNs'], 'Missing/out-of-range first-row time')
        boundary_reached = args['prefix-probes'] > 0 and oracle['rows'] >= args['prefix-probes'] // args['width']
        boundary_keys = ('sourceLazyCallsAtPrefixBoundary', 'projectedMaterializedValuesAtPrefixBoundary',
                         'prefixConsumeNs', 'tailConsumeNs')
        require(all(nonnegative_int(sample[k]) if boundary_reached else sample[k] is None for k in boundary_keys),
                'Wrong availability of phase-boundary observations')
        if boundary_reached:
            require(sample['prefixConsumeNs'] + sample['tailConsumeNs'] == sample['consumeNs']
                    and sample['sourceLazyCallsAtPrefixBoundary'] <= sample['counters']['lazyValueCalls']
                    and sample['projectedMaterializedValuesAtPrefixBoundary'] <= sample['projectedMaterializedValues'],
                    'Phase counters or timing intervals do not reconcile')
        counters = sample['counters']
        require(all(nonnegative_int(counters[k]) for k in (*ROUTE_COUNTERS, 'lazyValueCalls')),
                'Malformed execution counters')
        require(nonnegative_int(sample['projectedMaterializedValues']), 'Invalid projected materialization count')
        subset(counters, qualified['sampleCounters'], 'Qualified native counters')
        subset(sample, qualified['projection'], 'Qualified projection opportunities')
        require(counters['hostedGeneric'] == counters['unhostedHardDeclines'] == 0
                and sample['successfulSelections']
                and not any('forced' in route['mode'] for route in sample['successfulSelections']), 'AUTO/root route failed')
        if qualified['measuredTier'] == 'ordered-factorized':
            subset(counters, ORDERED_COUNTERS, 'Actual ordered-factorized execution')
            require(sample['successfulSelections'] == ORDERED_SELECTIONS,
                    'Qualified native ordered-factorized selection changed')
        elif sample['stage'] == 'measurement':
            compiled = counters['compiledBinds'] + counters['aggregateCompiledBinds']
            interpreted = counters['interpretedBinds'] + counters['aggregateInterpretedBinds']
            require((compiled > 0 and interpreted == 0) if qualified['measuredTier'] == 'compiled'
                    else (interpreted > 0 and compiled == 0), 'Measured IR tier differs from qualification')
        adjacency = sample['adjacency']
        require(adjacency['stateBefore'] == adjacency['stateAfter'] == 'ACTIVE'
                and adjacency['appliedRevisionBefore'] == adjacency['currentRevisionBefore'] ==
                adjacency['appliedRevisionAfter'] == adjacency['currentRevisionAfter'] == setup['currentDataRevision']
                and adjacency['lookupHits'] >= qualified['minimumAdjacencyLookupHits'], 'Adjacency route/readiness changed')
        count = int(arm != 'ordinary')
        require(sample['memoOpenedDelta'] == sample['memoClosedDelta'] == len(sample['memoOwners']) == count,
                'Wrong memo owner lifecycle')
        if count:
            owner = sample['memoOwners'][0]
            inspect_owner(protocol, owner, sample, index, arm)
            if owners:
                require(owner['lazyValueCallsAtOpen'] >= owners[-1]['lazyValueCallsAtClose'], 'Owner intervals overlap')
            owners.append(owner)
        if args['consumption'] == 'full':
            # Exact qualification establishes these exposure identities for the fully consumed
            # ordered fixtures. They detect integration bypasses without prescribing hit rates,
            # source-call counts, collision outcomes, capacities or latency.
            hits = sum(owner['hits'] for owner in sample['memoOwners'])
            require(sample['projectedMaterializedValues'] + hits == sample['projectedOpportunities'],
                    'Full projected exposure does not reconcile with memo hits/materializations')
            for owner in sample['memoOwners']:
                expected_probes = 8192 if owner['lowHitDisable'] else sample['projectedOpportunities']
                require(owner['probes'] == expected_probes, 'Full projected exposure bypassed the enabled memo')
    count = 0 if arm == 'ordinary' else 13
    subset(end, {'harnessReturned': True, 'queries': 13, 'warmups': 8, 'measurements': 5,
        'hostedGenericTotal': 0, 'unhostedHardDeclinesTotal': 0,
        'semanticNativeCompilesTotal': sum(s['counters']['semanticNativeCompiles'] for s in samples),
        'memoOpenedTotal': count, 'memoClosedTotal': count, 'memoStatisticsSize': count,
        'memoOverflowCount': 0, 'ledgerAfterBytes': 0}, 'Completion/root audit')
    measured = [metric_values(sample) for sample in samples[8:]]
    medians = {key: aggregate(m[key] for m in measured) for key in measured[0]}
    means = {key: aggregate((m[key] for m in measured), statistics.fmean) for key in measured[0]}
    owner_medians = {key: statistics.median(o[key] for o in owners[8:]) for key in OWNER_FIELDS} if owners else {}
    if owners:
        owner_medians['hitRate'] = aggregate(o['hits'] / o['probes'] if o['probes'] else None for o in owners[8:])
    return {'ordinal': slot['ordinal'], 'round': slot['round'], 'fixture': slot['fixture'], 'arm': arm,
            'directory': str(folder), 'metadata': metadata, 'samples': samples, 'owners': owners,
            'process': process, 'medians': medians, 'means': means, 'ownerMedians': owner_medians,
            'coldFirstQuery': metric_values(samples[0]),
            'routeSignature': object_sha([route(sample) for sample in samples]), 'gc': gc_summary(folder / 'gc.log')}


def match_runs(protocol, runs):
    metadata, routes, indexed = {}, {}, {}
    previous_end = 0
    for run in runs:
        require(run['process']['startedEpochNs'] >= previous_end, 'JVM intervals overlap')
        previous_end = run['process']['finishedEpochNs']
        fixture = run['fixture']
        normalized = normalized_metadata(run['metadata'])
        metadata.setdefault(fixture, normalized)
        require(metadata[fixture] == normalized, 'Matched fixture metadata differs')
        signature = [route(sample) for sample in run['samples']]
        routes.setdefault(fixture, signature)
        require(routes[fixture] == signature, 'Cross-arm or cross-round route/tier/adjacency changed')
        key = (fixture, run['round'], run['arm'])
        require(key not in indexed, 'Duplicate fixture/round/arm')
        indexed[key] = run
    paired = 0
    for fixture in protocol['fixtureOrder']:
        for round_index in range(6):
            for numerator, denominator in PAIRS:
                if (fixture, round_index, numerator) in indexed and (fixture, round_index, denominator) in indexed:
                    paired += 13
    return paired


def ratios_summary(pairs):
    valid = [v for v in pairs if v is not None]
    return {'pairedRatios': pairs, 'definedPairs': len(valid),
            'medianRatio': statistics.median(valid) if valid else None,
            'range': [min(valid), max(valid)] if valid else None,
            'allSixBelowOne': len(valid) == 6 and all(v < 1 for v in valid)}


def summarize(protocol, runs):
    count = len(protocol['schedule'])
    require(len(runs) == count and [run['ordinal'] for run in runs] == list(range(count)),
            'No accepted estimates from an incomplete cohort')
    paired = match_runs(protocol, runs)
    require(paired == count * 13, 'Incomplete paired route checks')
    indexed = {(run['fixture'], run['round'], run['arm']): run for run in runs}
    comparisons, absolutes = [], []
    for fixture in protocol['fixtureOrder']:
        for arm in ARMS:
            selected = [indexed[fixture, i, arm] for i in range(6)]
            measured_samples = [s for run in selected for s in run['samples'][8:]]
            measured_owners = [o for run in selected for o in run['owners'][8:]]
            absolutes.append({'fixture': fixture, 'arm': arm,
                'medianOfJvmMedians': {key: aggregate(run['medians'][key] for run in selected)
                                       for key in selected[0]['medians']},
                'secondaryMedianOfJvmMeans': {key: aggregate(run['means'][key] for run in selected)
                                              for key in selected[0]['means']},
                'coldFirstQueryMedians': {key: aggregate(run['coldFirstQuery'][key] for run in selected)
                                         for key in selected[0]['coldFirstQuery']},
                'ownerMedianOfJvmMedians': {key: aggregate(run['ownerMedians'][key] for run in selected)
                                            for key in selected[0]['ownerMedians']},
                'measuredOwnerRanges': {key: [min(o[key] for o in measured_owners), max(o[key] for o in measured_owners)]
                                        for key in OWNER_FIELDS} if measured_owners else {},
                'measuredOwnerEventTotals': {key: sum(o[key] for o in measured_owners)
                                             for key in OWNER_EVENTS} if measured_owners else {},
                'measuredSourceCallRange': [min(s['counters']['lazyValueCalls'] for s in measured_samples),
                                             max(s['counters']['lazyValueCalls'] for s in measured_samples)],
                'wholeJvmGcMedians': {key: statistics.median(run['gc'][key] for run in selected)
                                      for key in ('gcIdsObserved', 'pauseCount', 'pauseMs', 'pauseMaxMs',
                                                  'completedConcurrentCycles', 'concurrentCycleMs')}})
        for numerator, denominator in PAIRS:
            estimates = {}
            for label, field in (('primary', 'medians'), ('secondaryMeanSensitivity', 'means')):
                metrics = {}
                for key in indexed[fixture, 0, numerator][field]:
                    values = []
                    for i in range(6):
                        a, b = indexed[fixture, i, numerator][field][key], indexed[fixture, i, denominator][field][key]
                        values.append(a / b if a is not None and b not in (None, 0) else None)
                    metrics[key] = ratios_summary(values)
                estimates[label] = metrics
            source_differences = [a['counters']['lazyValueCalls'] - b['counters']['lazyValueCalls']
                for i in range(6) for a, b in zip(indexed[fixture, i, numerator]['samples'][8:],
                                                   indexed[fixture, i, denominator]['samples'][8:], strict=True)]
            primary = estimates['primary']['totalNs']['medianRatio']
            secondary = estimates['secondaryMeanSensitivity']['totalNs']['medianRatio']
            comparisons.append({'fixture': fixture, 'candidate': numerator, 'comparator': denominator,
                **estimates, 'latencyDirectionDisagrees': (primary < 1) != (secondary < 1),
                'measuredSourceCallDifference': {'numeratorMinusDenominator': source_differences,
                    'equalQueries': source_differences.count(0), 'totalMatchedQueries': 30,
                    'range': [min(source_differences), max(source_differences)]}})
    return {'complete': True, 'protocolSha256': sha(Path(protocol['cohort']) / 'protocol.json'),
            'counts': {**protocol['expectedCounts'], 'pairedQueries': paired},
            'allResultRouteAndCleanupGatesPassed': True,
            **{key: protocol[key] for key in ('estimator', 'secondaryEstimator', 'pooling', 'memoryScope',
                                               'gcScope', 'decision', 'admission', 'routing',
                                               'fixtureOrderingBasis', 'roundFixtureOrders')},
            'counterInterpretation': 'collectedMisses counts cleared occupied slots before key comparison, '
                                     'not necessarily additional same-key source calls. Occupancy at close is not '
                                     'a count of live weak referents. Always mode may grow under unchanged cumulative '
                                     'hit/collision rules; this is not a fixed-capacity ablation.',
            'absolutes': absolutes, 'comparisons': comparisons,
            'jvmResults': [{key: run[key] for key in ('ordinal', 'round', 'fixture', 'arm', 'directory',
                                                    'medians', 'means', 'ownerMedians', 'coldFirstQuery',
                                                    'routeSignature', 'gc')} for run in runs]}


def markdown(result):
    counts = result['counts']
    lines = ['# Finite phase admission comparison', '',
             f"All {counts['jvms']} scheduled JVMs, {counts['queries']} queries and {counts['measurements']} "
             'measured queries passed the frozen result, route, ownership and cleanup gates.', '',
             'The primary estimator pairs the five-query median of each JVM within its round and fixture. '
             'The secondary sensitivity uses the arithmetic mean of the same five samples; it was specified '
             'before this cohort and never replaces the primary estimator. Ratios below one favor the numerator.', '',
             '| Fixture | Comparison | Primary latency | Secondary mean latency | Primary allocation | Caller allocation | Direction differs |',
             '| --- | --- | ---: | ---: | ---: | ---: | --- |']
    for c in result['comparisons']:
        p, s = c['primary'], c['secondaryMeanSensitivity']
        lines.append(f"| {c['fixture']} | {c['candidate']}/{c['comparator']} | {p['totalNs']['medianRatio']:.6f} | "
                     f"{s['totalNs']['medianRatio']:.6f} | {p['allThreadAllocatedBytes']['medianRatio']:.6f} | "
                     f"{p['callerThreadAllocatedBytes']['medianRatio']:.6f} | {c['latencyDirectionDisagrees']} |")
    lines += ['', '## Every paired observation', '',
              '| Fixture | Comparison | Estimator / metric | Round 1 | Round 2 | Round 3 | Round 4 | Round 5 | Round 6 |',
              '| --- | --- | --- | ---: | ---: | ---: | ---: | ---: | ---: |']
    for c in result['comparisons']:
        for estimator, metric in (('primary', 'totalNs'), ('secondaryMeanSensitivity', 'totalNs'),
                                   ('primary', 'allThreadAllocatedBytes'), ('primary', 'callerThreadAllocatedBytes')):
            pairs = c[estimator][metric]['pairedRatios']
            cells = ' | '.join('n/a' if v is None else f'{v:.6f}' for v in pairs)
            lines.append(f"| {c['fixture']} | {c['candidate']}/{c['comparator']} | {estimator}/{metric} | {cells} |")
    lines += ['', '## Absolute query measurements', '',
              'Values below are medians of the six process medians, not pooled query medians.', '',
              '| Fixture | Arm | Total ms | Allocation bytes | Prepare ms | Evaluate ms | Consume ms | Close ms | Ledger peak bytes | Source calls |',
              '| --- | --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: |']
    for item in result['absolutes']:
        m = item['medianOfJvmMedians']
        lines.append(f"| {item['fixture']} | {item['arm']} | {m['totalNs']/1e6:.4f} | {m['allThreadAllocatedBytes']:.0f} | "
                     f"{m['prepareNs']/1e6:.4f} | {m['evaluateNs']/1e6:.4f} | {m['consumeNs']/1e6:.4f} | "
                     f"{m['closeNs']/1e6:.4f} | {m['ledgerPeakBytes']:.0f} | {m['lazyValueCalls']:.0f} |")
    lines += ['', 'The JSON also contains first-row and phase timing, retained-read time, cold first-query measurements, '
              'all owner counter ranges and totals, and the natural-GC summary of each JVM.', '',
              '## Interpretation limits', '', result['decision'], '', result['memoryScope'], '', result['gcScope'], '',
              result['counterInterpretation'], '', result['pooling'], '']
    return '\n'.join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--cohort', type=Path, required=True)
    parser.add_argument('--output', type=Path, required=True)
    args = parser.parse_args()
    cohort = args.cohort.resolve(strict=True)
    with (cohort / 'runner.lock').open('a') as lock:
        fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        require(not (cohort / 'failure.json').exists(), 'Cohort has a permanent failure receipt')
        protocol = frozen_protocol(cohort)
        count = len(protocol['schedule'])
        claims = sorted((cohort / 'claims').iterdir())
        require([p.name for p in claims] == [claim_name(i) for i in range(count)], 'Incomplete or extra claim set')
        require({p.name for p in cohort.glob('round-*')} == {Path(s['directory']).name for s in protocol['schedule']},
                'Unclaimed, missing or extra run directory')
        runs = [inspect_slot(protocol, slot, require_completion=True) for slot in protocol['schedule']]
        result = summarize(protocol, runs)
        output = args.output.resolve()
        output.mkdir(parents=True, exist_ok=False)
        (output / 'results.json').write_text(json.dumps(result, indent=2, sort_keys=True, allow_nan=False) + '\n')
        (output / 'RESULTS.md').write_text(markdown(result))
        print(json.dumps({'complete': True, 'counts': result['counts'], 'output': str(output)}))


if __name__ == '__main__':
    main()
